// Token Radar's dashboard, radar-5. It reads window.RADAR (written beside
// dashboard/ by main.ts) and renders the ranked board, a filterable table,
// and a per-protocol detail view with the model's own inputs and the
// protocol's farm plan. No network: every byte it shows is in data.js. The
// farm plan is rendered from the row itself, never re-derived in the page,
// so the page and board.json cannot disagree about it. The implied value is
// recomputed in the detail view from the row's own multipliers and checked
// against the board.
(function () {
  'use strict';

  var DATA = window.RADAR;
  if (!DATA) return;
  var app = document.getElementById('board');
  var state = { q: '', category: 'all', chain: 'all', tab: 'pre-token', sort: 'implied', dir: -1, selected: null };

  var usd = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  function fmtUsd(n) {
    if (n === null || n === undefined || !isFinite(n)) return 'n/a';
    if (Math.abs(n) >= 1e9) return '$' + (n / 1e9).toFixed(2) + 'B';
    if (Math.abs(n) >= 1e6) return '$' + (n / 1e6).toFixed(1) + 'M';
    if (Math.abs(n) >= 1e3) return '$' + Math.round(n / 1e3) + 'K';
    return usd.format(n);
  }
  function fmtPct(n) {
    if (n === null || n === undefined || !isFinite(n)) return 'n/a';
    return (n > 0 ? '+' : '') + n.toFixed(2) + '%';
  }
  function fmtAge(days) {
    if (days === null || days === undefined) return 'unknown';
    if (days >= 365) return (days / 365).toFixed(1) + 'y';
    return Math.max(0, Math.round(days)) + 'd';
  }
  // The model, recomputed from the row's own multipliers: TVL x category
  // multiple x growth x maturity x the pre-token discount.
  function impliedOf(row) {
    return Math.max(1, Math.round(row.tvl_usd * row.category_multiple * row.growth_multiplier * row.maturity_multiplier * DATA.model.pre_token_discount));
  }

  function el(tag, attrs) {
    var node = document.createElement(tag);
    if (attrs) {
      Object.keys(attrs).forEach(function (k) {
        if (k === 'class') node.className = attrs[k];
        else if (k === 'text') node.textContent = attrs[k];
        else if (k === 'html') node.innerHTML = attrs[k];
        else if (k.slice(0, 2) === 'on') node.addEventListener(k.slice(2), attrs[k]);
        else if (attrs[k] !== null && attrs[k] !== undefined) node.setAttribute(k, attrs[k]);
      });
    }
    for (var i = 2; i < arguments.length; i++) {
      var child = arguments[i];
      if (child === null || child === undefined) continue;
      if (Array.isArray(child)) child.forEach(function (c) { if (c) node.appendChild(c); });
      else if (typeof child === 'string') node.appendChild(document.createTextNode(child));
      else node.appendChild(child);
    }
    return node;
  }
  function fact(label, big, small) {
    return el('div', { class: 'fact' }, el('span', { text: label }), el('b', { text: big }), el('small', { text: small }));
  }

  function readHash() {
    var hash = window.location.hash.replace(/^#/, '');
    if (!hash) return;
    var params = new URLSearchParams(hash);
    if (params.get('q')) state.q = params.get('q');
    if (params.get('p')) state.selected = params.get('p');
    if (params.get('category')) state.category = params.get('category');
    if (params.get('chain')) state.chain = params.get('chain');
    if (params.get('tab')) state.tab = params.get('tab');
  }
  function writeHash() {
    var params = new URLSearchParams();
    if (state.q) params.set('q', state.q);
    if (state.category !== 'all') params.set('category', state.category);
    if (state.chain !== 'all') params.set('chain', state.chain);
    if (state.tab !== 'pre-token') params.set('tab', state.tab);
    if (state.selected) params.set('p', state.selected);
    var next = params.toString();
    if (next) window.history.replaceState(null, '', '#' + next);
    else window.history.replaceState(null, '', window.location.pathname + window.location.search);
  }

  function visibleRows() {
    var q = state.q.trim().toLowerCase();
    return DATA.rows.filter(function (r) {
      if (state.tab === 'watchlist' && !r.watchlist) return false;
      if (state.category !== 'all' && r.category !== state.category) return false;
      if (state.chain !== 'all' && !(r.chains || []).includes(state.chain)) return false;
      if (!q) return true;
      var hay = [r.name, r.slug, r.category, (r.chains || []).join(' ')].join(' ').toLowerCase();
      return hay.indexOf(q) >= 0;
    });
  }
  function sortedRows(list) {
    var key = state.sort;
    return list.slice().sort(function (a, b) {
      var av, bv;
      if (key === 'name') { av = a.name.toLowerCase(); bv = b.name.toLowerCase(); }
      else if (key === 'tvl') { av = a.tvl_usd; bv = b.tvl_usd; }
      else if (key === 'growth') { av = a.change_7d === null ? -Infinity : a.change_7d; bv = b.change_7d === null ? -Infinity : b.change_7d; }
      else if (key === 'age') { av = a.age_days === null ? Infinity : a.age_days; bv = b.age_days === null ? Infinity : b.age_days; }
      else if (key === 'verdict') { av = a.farm_net_low_usd; bv = b.farm_net_low_usd; }
      else { av = a.implied_value_usd; bv = b.implied_value_usd; }
      if (av < bv) return -state.dir;
      if (av > bv) return state.dir;
      return a.slug < b.slug ? -1 : a.slug > b.slug ? 1 : 0;
    });
  }

  function header() {
    return el('header', { class: 'top' },
      el('div', { class: 'brand' }, el('span', { class: 'mark' }), el('span', { class: 'brand-name', text: 'Token Radar' }), el('span', { class: 'brand-sub', text: 'pre-token protocols, ranked' })),
      el('div', { class: 'top-meta' },
        el('span', { text: 'Snapshot ' + DATA.as_of }),
        el('span', { text: 'DefiLlama protocol index' }),
        el('span', { text: DATA.model_version + ' model' })
      )
    );
  }

  function lede() {
    var top = DATA.rows[0];
    var aboveFloor = DATA.rows.filter(function (r) { return !r.watchlist && r.tvl_usd >= DATA.floor_usd; }).length;
    return el('section', { class: 'lede' },
      el('div', null,
        el('h1', { text: DATA.watchlist_size + ' watchlist protocols, ranked by what their token would be worth' }),
        el('p', { text: 'The watchlist is the floor: every protocol with at least $' + Math.round(DATA.floor_usd / 1e6) + 'M of TVL and no token on record. The early radar adds ' + DATA.early_size + ' pre-token protocols that pass the same screen, ' + aboveFloor + ' of them above that floor: the board ranks what the live market would pay, not the watchlist\u2019s cutoff. Implied value is priced off a size curve fitted on the live market in this same snapshot: log market cap on log TVL, with one offset per category — exchange tokens left out of the fit, because their multiples price the exchange, not the protocol. Size itself predicts the multiple — larger protocols trade at lower multiples — and the curve is tested out of sample four ways before the board is trusted. It is a model, not a price.' })
      ),
      el('div', { class: 'facts' },
        fact('Watchlist covered', DATA.watchlist_size + ' / ' + DATA.watchlist_size, 'every watchlist protocol is ranked'),
        fact('Pre-token rows', String(DATA.board_size), DATA.early_size + ' early rows that pass the launch screen'),
        fact('Top implied value', top ? fmtUsd(top.implied_value_usd) : 'n/a', top ? top.name : ''),
        fact('Screened out', String(DATA.screened_out), 'pre-token protocols that fail the launch screen')
      )
    );
  }

  function validationPanel() {
    var v = DATA.validation;
    if (!v) return null;
    var verdicts = { FARM: 0, THIN: 0, SKIP: 0 };
    DATA.rows.forEach(function (r) { verdicts[r.farm_verdict]++; });
    return el('section', { class: 'panel validation' },
      el('h2', { text: 'The model, tested out of sample — four held-out ways' }),
      el('p', { class: 'sub', text: 'The curve is fitted on the live market in this same snapshot — so before the board is trusted, it is tested on data the fit never saw. Leave-one-out refits the curve without each live protocol and predicts its market cap from its TVL; the time-split fits on older listings and tests on newer ones; the walk-forward grows the training window and predicts every dated protocol once as a future listing; leave-one-category-out predicts a whole category blind, with no offset of its own. The conformal intervals are built from those errors, and the bootstrap resamples the live comparables and rebuilds the board. A curve is a pricing kernel, not a price: the median protocol is mispriced by a factor of ' + Math.max(1, Math.round(v.loocv.median_error_multiple)) + ', so a row is a candidate to research, never a valuation to trade on.' }),
      el('div', { class: 'facts' },
        fact('Leave-one-out, median error', 'x' + v.loocv.median_error_multiple.toFixed(2), v.loocv.n + ' live protocols; ' + Math.round(v.loocv.within_2x * 100) + '% within 2x, ' + Math.round(v.loocv.within_3x * 100) + '% within 3x'),
        fact('Time-split, median error', 'x' + v.time_split.median_error_multiple.toFixed(2), 'fitted on ' + v.time_split.n_train + ' listings before ' + v.time_split.cut_date + ', tested on ' + v.time_split.n_test + ' newer ones'),
        fact('Walk-forward, median error', 'x' + v.walk_forward.median_error_multiple.toFixed(2), 'every one of ' + v.walk_forward.n_test + ' dated protocols predicted once as a future listing; ' + Math.round(v.walk_forward.within_2x * 100) + '% within 2x'),
        fact('Leave-one-category-out', 'x' + v.leave_one_category_out.median_error_multiple.toFixed(2), v.leave_one_category_out.n_categories + ' categories predicted blind; ' + Math.round(v.leave_one_category_out.within_2x * 100) + '% within 2x'),
        fact('Conformal 90% intervals', Math.round(v.conformal.coverage * 100) + '% covered', 'true market cap inside its interval for ' + Math.round(v.conformal.coverage * 100) + '% of ' + v.conformal.n + ' protocols; median interval spans x' + v.conformal.median_interval_factor.toFixed(2)),
        fact('Bootstrap top 10', v.bootstrap.top10_overlap_mean.toFixed(2) + ' / 10', v.bootstrap.rounds + ' resamples; each top-10 row moves ' + v.bootstrap.top10_rank_shift_mean.toFixed(2) + ' ranks, rank 1 stays in ' + Math.round(v.bootstrap.rank1_stays_share * 100) + '%'),
        fact('Farm verdicts', verdicts.FARM + ' FARM', verdicts.THIN + ' THIN, ' + verdicts.SKIP + ' SKIP of ' + DATA.board_size + ' rows, netted at the band\u2019s low end')
      )
    );
  }

  function modelPanel() {
    var m = DATA.model;
    var comps = DATA.comparables.slice(0, 10);
    var rows = comps.map(function (c) {
      return el('tr', null,
        el('td', { text: c.category }),
        el('td', { class: 'num', text: String(c.n) }),
        el('td', { class: 'num', text: (c.offset >= 0 ? '+' : '') + c.offset.toFixed(3) }),
        el('td', { class: 'num', text: c.multiple.toFixed(3) + 'x' })
      );
    });
    var reasons = DATA.screen_reasons.map(function (r) { return r.count + ' ' + r.reason; }).join('; ');
    return el('section', { class: 'panel model' },
      el('h2', { text: 'How implied value is computed' }),
      el('p', { class: 'sub', text: 'One function scores every protocol. No name is special-cased, and no row is hand-picked. The size curve is fitted on the live-token protocols in this same snapshot, leaving out exchange tokens: ln(market cap) = ' + DATA.curve.intercept.toFixed(3) + ' + ' + DATA.curve.slope.toFixed(3) + ' x ln(TVL), plus one offset per category — the mean residual of its live protocols, shrunk toward zero with ' + m.shrink_pseudo + ' pseudo-observations, so a category with one live protocol does not inherit its offset wholesale. A protocol\u2019s fitted multiple is the curve\u2019s prediction at its own TVL, clamped to ' + m.multiple_floor + 'x–' + m.multiple_cap + 'x.' }),
      el('div', { class: 'formula' }, 'implied = round( exp(' + DATA.curve.intercept.toFixed(3) + ' + ' + DATA.curve.slope.toFixed(3) + ' x ln TVL + offset) x (1 + clamp(7d, ' + m.growth_floor + ', ' + m.growth_cap + ') / 100 x ' + m.growth_weight + ') x (' + m.maturity_floor + ' + min(age, ' + m.maturity_days + ') / ' + m.maturity_days + ' x ' + m.maturity_range + ') x ' + m.pre_token_discount + ' )'),
      el('table', { class: 'mini' },
        el('caption', { class: 'sub', text: 'Live comparables by category: the ten largest categories. Offset is the category\u2019s shrunk log-point offset in the curve; multiple is the fitted multiple at the category\u2019s median live TVL.' }),
        el('thead', null, el('tr', null,
          el('th', { text: 'Category' }), el('th', { class: 'num', text: 'Live n' }), el('th', { class: 'num', text: 'Curve offset' }), el('th', { class: 'num', text: 'Multiple at median TVL' }))),
        el('tbody', null, rows)
      ),
      el('p', { class: 'sub', text: 'Screened out: ' + DATA.screened_out + ' pre-token protocols fail the launch screen — ' + reasons + '. Above the floor, protocols the watchlist leaves out are ranked too when they pass the same screen — ' + DATA.rows.filter(function (r) { return !r.watchlist && r.tvl_usd >= DATA.floor_usd; }).length + ' of them — because the board ranks what the live market would pay, not the watchlist\u2019s cutoff. A protocol records no token; that is not proof it has none.' })
    );
  }

  function controls() {
    var categories = Array.from(new Set(DATA.rows.map(function (r) { return r.category || 'Other'; }))).sort();
    var chains = Array.from(new Set(DATA.rows.reduce(function (acc, r) { return acc.concat(r.chains || []); }, []))).sort();
    var search = el('input', { type: 'search', id: 'q', placeholder: 'Search name or chain', value: state.q, 'aria-label': 'Search the board' });
    search.addEventListener('input', function () { state.q = search.value; writeHash(); render(); });
    var cat = el('select', { id: 'category', 'aria-label': 'Filter by category' },
      el('option', { value: 'all', text: 'All categories' }),
      categories.map(function (c) { return el('option', { value: c, text: c, selected: c === state.category ? 'selected' : null }); })
    );
    cat.addEventListener('change', function () { state.category = cat.value; writeHash(); render(); });
    var chain = el('select', { id: 'chain', 'aria-label': 'Filter by chain' },
      el('option', { value: 'all', text: 'All chains' }),
      chains.map(function (c) { return el('option', { value: c, text: c, selected: c === state.chain ? 'selected' : null }); })
    );
    chain.addEventListener('change', function () { state.chain = chain.value; writeHash(); render(); });
    function tabBtn(tab, label) {
      return el('button', { type: 'button', 'aria-pressed': state.tab === tab ? 'true' : 'false', text: label, onclick: function () { state.tab = tab; writeHash(); render(); } });
    }
    var count = state.tab === 'live' ? DATA.live.length + ' live-token protocols' : visibleRows().length + ' rows shown';
    return el('div', { class: 'controls' },
      el('div', { class: 'field' }, el('label', { for: 'q', text: 'Search' }), search),
      el('div', { class: 'field' }, el('label', { for: 'category', text: 'Category' }), cat),
      el('div', { class: 'field' }, el('label', { for: 'chain', text: 'Chain' }), chain),
      el('div', { class: 'field' }, el('span', { class: 'sub', text: 'View' }), el('div', { class: 'tabs' }, tabBtn('pre-token', 'Pre-token'), tabBtn('watchlist', 'Watchlist'), tabBtn('live', 'Live token'))),
      el('span', { class: 'count', text: count })
    );
